	local boton = script.Parent	
	local marco = boton.Parent	

	-- Buscamos el cuadro verde (Caja de texto o TextBox)	
	-- Lo buscamos por su "Clase" para que no importe el nombre	
	local cajaDeTexto = marco:FindFirstChildOfClass("TextBox")	

	boton.MouseButton1Click:Connect(function()	
	    if cajaDeTexto then	
	        local codigo = cajaDeTexto.Text	

	        if codigo ~= "" and codigo ~= "TextBox" then	
	            print("Project g00byd0lan: Intentando ejecutar...")	

	            local success, err = pcall(function()	
	                -- Delta usará loadstring para ejecutar el texto de la caja	
	                local f = loadstring(codigo)	
	                if f then 	
	                    f() 	
	                else	
	                    warn("Error: El código escrito está incompleto o mal.")	
	                end	
	            end)	

	            if not success then	
	                warn("Error al ejecutar: " .. tostring(err))	
	            end	
	        else	
	            warn("Escribe algo en el cuadro verde primero.")	
	        end	
	    else	
	        warn("No se encontró el TextBox dentro del Marco.")	
	    end	
	end)	
